  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "UNC2025, which shares the aminopyridine and N-aryl heteroaromatic/morpholine-piperazine motif, showed exceptional BBB permeability with a brain/plasma AUC ratio of 2.0 in mice, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "[11C]MC113, containing the same para-(morpholinomethyl)phenyl group as the query, showed high brain uptake in mouse microPET, indicating that this motif does not prevent BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "AG-0029, a morpholinomethylphenyl-containing heteroaromatic ligand, rapidly crossed the BBB in rat PET and engaged central receptors, supporting CNS access for similarly sized and moderately polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Structurally related compounds with morpholine/piperidine and benzylamine motifs crossed the BBB with a brain-to-plasma ratio of ~1:1 in rats, demonstrating adequate CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "EPZ-5676-related material showed low brain/spinal cord radioactivity in rats, but this analogue contains an additional polar hydroxyamidine and higher polar surface area, making its impermeability less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple structurally related CNS-penetrant analogues with morpholine/piperazine and aminopyridine motifs show robust brain uptake, and the query's physicochemical profile is compatible with passive diffusion and low efflux liability. The single impermeable analogue is less transferable due to additional polar functionality.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or PET measurement exists for the query molecule.",
    "Morgan similarities to the evidence set are modest (0.24-0.29), limiting exact structural transfer.",
    "Efflux-transporter status for the query is not experimentally defined."
  ],
